// === Tab: Sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io/

let composition = [];
// 0: full yellow circle
// 1: empty black circle
let n = 16; // number of elements per lign and column
let size = 512/16; // size of each element
let margin = 44;
let yellow;

let randInt = (x) => (floor(random(x)));

function setup() {
  createCanvas(600, 600);
  //// noLoop() removed for animation
	colorMode(HSB, 1);
	yellow = color(0.15, 0.9, 1);
	noStroke();
	frameRate(1);
	rectMode(CENTER);

	for (let i = 0; i < n; i++) {
		composition.push([]);
		for (let j = 0; j < n; j++) {
			composition[i].push(randInt(2));
		}
	}
}

function draw() {
	background(yellow);
  drawComposition();
	//changeOneElement();
}

function drawComposition() {
	push();
	translate(margin, margin);

	let a = 3/4;
	for (let i = 0; i < n; i++) {
		for (let j = 0; j < n; j++) {
			let x = (i+1/2) * size;
			let y = (j+1/2) * size;
			switch (composition[i][j]) {
				case 0:
					fill(0);
					square(x, y, size);
					fill(yellow);
					circle(x, y, size*a);
					break;
				case 1:
					fill(yellow);
					square(x, y, size);
					fill(0);
					circle(x, y, size*a);
			}
		}
	}
	for (let i = 0; i < n; i++) {
		for (let j = 0; j < n; j++) {
			if ((i < n-1) && (composition[i][j] == composition[i+1][j]) && (composition[i][j] == 0)) {
				fill(yellow);
				rect((i+1)*size, (j+1/2)*size, size, size*a);
			} 
			if ((j < n-1) && (composition[i][j] == composition[i][j+1]) && (composition[i][j] == 1)) {
				fill(0);
				rect((i+1/2)*size, (j+1)*size, size*a, size);
			}
		}
	}

	a = 1/2;
	for (let i = 0; i < n; i++) {
		for (let j = 0; j < n; j++) {
			var x = (i+1/2) * size;
			var y = (j+1/2) * size;
			switch (composition[i][j]) {
				case 0:
					fill(0);
					circle(x, y, size*a);
					break;
				case 1:
					fill(yellow);
					circle(x, y, size*a);
			}
		}
	}
	for (let i = 0; i < n; i++) {
		for (let j = 0; j < n; j++) {
			if (random() < 0.5) {
				if ((i < n-1) && (composition[i][j] == composition[i+1][j]) && (composition[i][j] == 0)) {
					fill(0);
					rect((i+1)*size, (j+1/2)*size, size, size*a);
				} 
				if ((j < n-1) && (composition[i][j] == composition[i][j+1]) && (composition[i][j] == 1)) {
					fill(yellow);
					rect((i+1/2)*size, (j+1)*size, size*a, size);
				}
			}
		}
	}
	pop();
}

function changeOneElement() {
	let i = randInt(n);
	let j = randInt(n);
	let oldEl = composition[i][j];
	let newEl;
	do {
		newEl = randInt(2);
	} while (newEl === oldEl);
	composition[i][j] = newEl;
}
